// Never trust incoming data, even from our own backend: check it before using it.
const event = $input.first().json.body || {};
const d = event.data || {};
const text = (t, max) => String(t ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
if (event.type !== 'lead.qualified') throw new Error('Unexpected event type - ' + text(event.type, 40));
if (!/^LD-[A-Za-z0-9-]{1,40}$/.test(d.leadId || '')) throw new Error('The event has no valid leadId');
if (d.classification !== 'Hot') throw new Error('Only Hot leads get an alert');

// First name only: no phone, email or address is ever in the event.
let message = 'HOT LEAD ' + d.leadId + ': ' + text(d.firstName, 40) + ', ' + text(d.serviceType, 40) + ', timeline ' + text(d.timeline, 30) + ', score ' + text(d.score, 5) + '. Call them first.';
if (d.reason) message += ' Why: ' + text(d.reason, 200);

return [{ json: { leadId: d.leadId, message: message.slice(0, 500) } }];

// Did the backend accept it? 2xx → continue with its answer (the JSON body).
// Anything else FAILS this run (→ WF4 escalates), labelled so a person knows what to do:
//   TEMPORARY (408, 429, 5xx): the backend had a problem; trying again later can work
//   PERMANENT (other 4xx):     retrying can never fix it, so it is NOT retried
// "No answer at all" never gets here: the HTTP node already retried that 3 times.
const r = $input.first().json;
const s = r.statusCode;
if (s >= 200 && s < 300) return [{ json: r.body ?? {} }];
const code = (r.body && r.body.error && r.body.error.code) || 'no error code';
const temporary = s === 408 || s === 429 || (s >= 500 && s <= 599);
throw new Error((temporary ? 'TEMPORARY' : 'PERMANENT') + ' backend answer to "Alert on the dashboard" - HTTP ' + s + ' ' + code + (temporary ? '' : ' (not retried, retrying cannot fix it)'));

